-- Paket 13.11.2026: cart quantity buttons (chunk 17) + mobile filters (new chunk, template 18). Text is hex-encoded on purpose.
SET NAMES utf8mb4;
SET SESSION group_concat_max_len = 100000;
-- ROLLBACK, filters only: puts template 18 back from hts_bak_20261113 and removes the new chunk.
UPDATE modx_site_templates t JOIN hts_bak_20261113 b ON b.kind = 'template' AND b.el_id = t.id SET t.content = b.body WHERE t.id = 18;
DELETE FROM modx_site_htmlsnippets WHERE name = 'HtsMobileFilters' AND snippet LIKE '%htsFiltersBound%';
SELECT CASE WHEN (SELECT COUNT(*) FROM hts_bak_20261113 WHERE kind = 'template' AND el_id = 18) = 0 THEN _utf8mb4 0xD09220D180D0B5D0B7D0B5D180D0B2D0BDD0BED0B920D182D0B0D0B1D0BBD0B8D186D0B520D0BDD0B5D18220D0BAD0BED0BFD0B8D0B820E2809420D0BED182D0BAD0B0D182D18BD0B2D0B0D182D18C20D0BDD0B5D187D0B5D0B3D0BE WHEN (SELECT content FROM modx_site_templates WHERE id = 18) NOT LIKE '%[[$HtsMobileFilters]]%' AND (SELECT COUNT(*) FROM modx_site_htmlsnippets WHERE name = 'HtsMobileFilters') = 0 THEN _utf8mb4 0xD0A4D0B8D0BBD18CD182D180D18B20D183D0B1D180D0B0D0BDD18B2C20D188D0B0D0B1D0BBD0BED0BD20D0B2D0BED0B7D0B2D180D0B0D189D191D0BD ELSE _utf8mb4 0xD09DD09520D0A1D09ED092D09FD090D094D090D095D0A220E2809420D181D182D0BED0BF2C20D181D0BAD180D0B8D0BDD188D0BED182 END AS itog;
